def transform(grid):
    """Keep and restore the large solid rectangular patches; clear stray marks."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    boxes = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            # The intended objects are sizeable rectangular patches; isolated
            # annotation pixels and short stray lines are discarded.
            if r1 - r0 + 1 >= 2 and c1 - c0 + 1 >= 2 and len(cells) >= 4:
                boxes.append((r0, r1, c0, c1, color))

    out = [[background] * w for _ in range(h)]
    for r0, r1, c0, c1, color in boxes:
        for r in range(r0, r1 + 1):
